def read_vulnerabilities(fh: Any) ->Dict[str, Any]:
    try:
        data = json.load(fh)
    except (json.JSONDecodeError, UnicodeDecodeError) as e:
        raise MalformedDatabase(reason=e)
    except TypeError as e:
        raise MalformedDatabase(reason=e)
    return data
